WITH flattened_attrs AS (SELECT id, service, host, context, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, COALESCE(context['trace'], 'none') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT CASE WHEN duration_sec >= 4.1 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, MAX(duration_sec) FILTER (WHERE service = 'billing') AS billing_max_duration_sec, COUNT(*) FILTER (WHERE service = 'billing') AS billing_rows, SIZE(COLLECT_SET(service)) AS num_services FROM flattened_attrs GROUP BY CASE WHEN duration_sec >= 4.1 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY num_services;
